@namespace sv_bddc16d24a29418db7eb37433b2272dc.Components.JobApplication

<nav class="step-indicator mb-4" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var stepIndex = i + 1;
            var isCompleted = CompletedSteps.Contains(stepIndex);
            var isCurrent = stepIndex == CurrentStep;
            var isClickable = isCompleted && !isCurrent;
            <li class="step-item @(isCurrent ? "active" : "") @(isCompleted ? "completed" : "") @(!isCurrent && !isCompleted ? "dimmed" : "")"
                @onclick="() => HandleClick(stepIndex)"
                @onclick:preventDefault
                role="@(isClickable ? "button" : "")"
                tabindex="@(isClickable ? 0 : -1)"
                aria-current="@(isCurrent ? "step" : null)">
                <span class="step-circle">
                    @if (isCompleted && !isCurrent)
                    {
                        <span class="checkmark">✓</span>
                    }
                    else
                    {
                        @stepIndex
                    }
                </span>
                <span class="step-label">@StepNames[i]</span>
            </li>
            @if (i < StepNames.Count - 1)
            {
                <li class="step-connector @(CompletedSteps.Contains(stepIndex) ? "completed" : "")" aria-hidden="true"></li>
            }
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter, EditorRequired] public IReadOnlyList<string> StepNames { get; set; } = [];
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private async Task HandleClick(int step)
    {
        if (CompletedSteps.Contains(step) && step != CurrentStep)
        {
            await OnStepClicked.InvokeAsync(step);
        }
    }
}

@namespace sv_bddc16d24a29418db7eb37433b2272dc.Components.JobApplication

.step-indicator {
    background: var(--bs-light, #f8f9fa);
    border-radius: 0.5rem;
    padding: 1rem 1.5rem;
}

.step-list {
    display: flex;
    align-items: center;
    list-style: none;
    padding: 0;
    margin: 0;
    gap: 0;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.4rem;
    flex-shrink: 0;
    cursor: default;
    transition: opacity 0.2s;
}

.step-item.completed:not(.active) {
    cursor: pointer;
}

.step-item.dimmed {
    opacity: 0.45;
}

.step-circle {
    width: 2.2rem;
    height: 2.2rem;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.9rem;
    border: 2px solid #dee2e6;
    background: white;
    color: #6c757d;
    transition: all 0.2s;
}

.step-item.active .step-circle {
    background: #0d6efd;
    border-color: #0d6efd;
    color: white;
}

.step-item.completed .step-circle {
    background: #198754;
    border-color: #198754;
    color: white;
}

.checkmark {
    font-size: 1rem;
}

.step-label {
    font-size: 0.78rem;
    font-weight: 500;
    color: #6c757d;
    text-align: center;
    white-space: nowrap;
}

.step-item.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step-item.completed .step-label {
    color: #198754;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #dee2e6;
    min-width: 1.5rem;
    margin: 0 0.25rem;
    margin-bottom: 1.4rem;
    transition: background 0.2s;
}

.step-connector.completed {
    background: #198754;
}

@namespace sv_bddc16d24a29418db7eb37433b2272dc.Components.JobApplication
@using sv_bddc16d24a29418db7eb37433b2272dc.Models

<div class="card mb-3">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center mb-3">
            <h6 class="card-title mb-0">Reference @(Index + 1)</h6>
            @if (CanRemove)
            {
                <button type="button" class="btn btn-outline-danger btn-sm" @onclick="OnRemove">Remove</button>
            }
        </div>
        <div class="row g-3">
            <div class="col-md-6">
                <label class="form-label">Full Name <span class="text-danger">*</span></label>
                <input class="form-control" @bind="Model.Name" @bind:event="oninput" placeholder="Reference name" />
            </div>
