    flex-direction: column;
    align-items: center;
    gap: 0.4rem;
    flex-shrink: 0;
    cursor: default;
    transition: opacity 0.2s;
}

.step-item.completed:not(.active) {
    cursor: pointer;
}

.step-item.dimmed {
    opacity: 0.45;
}

.step-circle {
    width: 2.2rem;
    height: 2.2rem;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.9rem;
    border: 2px solid #dee2e6;
    background: white;
    color: #6c757d;
    transition: all 0.2s;
}

.step-item.active .step-circle {
    background: #0d6efd;
    border-color: #0d6efd;
    color: white;
}

.step-item.completed .step-circle {
    background: #198754;
    border-color: #198754;
    color: white;
}

.checkmark {
    font-size: 1rem;
}

.step-label {
    font-size: 0.78rem;
    font-weight: 500;
    color: #6c757d;
    text-align: center;
    white-space: nowrap;
}

.step-item.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step-item.completed .step-label {
    color: #198754;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #dee2e6;
    min-width: 1.5rem;
    margin: 0 0.25rem;
    margin-bottom: 1.4rem;
    transition: background 0.2s;
}

.step-connector.completed {
    background: #198754;
}

